with candidate (n, title, artist, image_url, content, image_license, image_credit, image_page) as (
    values
    (1, '1808年5月3日、マドリード', 'フランシスコ・デ・ゴヤ', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/4/48/El_Tres_de_Mayo%2C_by_Francisco_de_Goya%2C_from_Prado_in_Google_Earth.jpg/960px-El_Tres_de_Mayo%2C_by_Francisco_de_Goya%2C_from_Prado_in_Google_Earth.jpg', '1808年5月2日にマドリード市民がナポレオン軍に対して起こした蜂起の翌日、捕らえられた市民が銃殺される場面を描いた作品です。フランス軍が去った後の1814年に、対になる《1808年5月2日》とともに制作されました。顔の見えない兵士の列と、ランタンの光に照らされて両腕を広げる白いシャツの男との対比が見どころです。名もない人々の死を正面から描いたこの絵は、のちの戦争を描く絵画に大きな影響を与えました。マドリードのプラド美術館が所蔵しています。', 'Public domain', null, 'https://commons.wikimedia.org/wiki/File:El_Tres_de_Mayo,_by_Francisco_de_Goya,_from_Prado_in_Google_Earth.jpg'),
    (2, '千里江山図', '王希孟', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/6/67/%E7%8E%8B%E5%B8%8C%E5%AD%9F%E5%8D%83%E9%87%8C%E6%B1%9F%E5%B1%B1%E5%9B%BE%E5%8D%B7.png/960px-%E7%8E%8B%E5%B8%8C%E5%AD%9F%E5%8D%83%E9%87%8C%E6%B1%9F%E5%B1%B1%E5%9B%BE%E5%8D%B7.png', '北宋の1113年ごろ、宮廷画院で学んでいた王希孟が十代の若さで描いたとされる絵巻です。長さ約12メートルの絹に、連なる山々と川、湖、村や橋、舟が続いていきます。鉱物の顔料による鮮やかな青と緑で山を彩る「青緑山水」の代表作で、巻物を少しずつ広げると、旅をするように景色が移り変わります。作者について伝わることはわずかで、残る作品はこの一点だけです。北京の故宮博物院が所蔵しています。', 'Public domain', null, 'https://commons.wikimedia.org/wiki/File:王希孟千里江山图卷.png')
), fresh as (
    select c.*, row_number() over (order by c.n) as k
    from candidate c
    where not exists (select 1 from public.daily_columns d where d.title = c.title)
), free_day as (
    select day::date as display_date, row_number() over (order by day) as k
    from generate_series(
        (now() at time zone 'Asia/Tokyo')::date,
        (now() at time zone 'Asia/Tokyo')::date + 2
            + (select count(*)::int from public.daily_columns
               where display_date >= (now() at time zone 'Asia/Tokyo')::date),
        interval '1 day') as day
    where not exists (select 1 from public.daily_columns d where d.display_date = day::date)
)
insert into public.daily_columns (title, artist, image_url, content, image_license, image_credit, image_page, display_date)
select f.title, f.artist, f.image_url, f.content, f.image_license, f.image_credit, f.image_page, d.display_date
from fresh f join free_day d using (k)
on conflict (display_date) do nothing;

insert into public.trending_articles (title, summary, content, image_url, keyword, source_url,
    image_license, image_credit, image_page)
values ('マティス版画展、2027年に国立西洋美術館で開催', 'ピエール＆タナ・マティス財団の版画コレクションを核に、マティスの「黒と白」の表現をたどる展覧会が2027年春に上野で開かれる。', '国立西洋美術館（東京・上野）で、2027年3月20日から7月19日まで「マティス 黒と白の詩学—ピエール＆タナ・マティス財団の版画コレクションを中心に」が開催される。ニューヨークのピエール＆タナ・マティス財団の版画コレクションを核に、関連する絵画やデッサンも展示する。マティスは生涯で800点以上の版画と多数の挿絵本を残し、版画では一部の例外を除いて黒と白の表現に徹した。希少な原版や、刷りに使われた紙の種類の比較も紹介し、挿絵本への注目も本展の特徴とされる。主催は国立西洋美術館と読売新聞社。', '', '展覧会', 'https://www.tokyoartbeat.com/articles/-/henri-matisse-nmwa-news-202610',
        null, null, null)
on conflict (source_url) do nothing;

insert into public.trending_articles (title, summary, content, image_url, keyword, source_url,
    image_license, image_credit, image_page)
values ('パウル・クレー大規模展、2027年に国立国際美術館で', 'デュッセルドルフの州立美術館が所蔵するクレー作品約120点を紹介する展覧会が大阪で開かれ、東京都美術館へ巡回する。', '国立国際美術館（大阪）で、2027年9月11日から12月26日まで「ノルトライン＝ヴェストファーレン州立美術館 パウル・クレー あいだの世界」が開催される。ドイツ・デュッセルドルフにある同館の所蔵品を中心に、クレー作品約120点を紹介する。同館は戦後の1960年、州政府が88点のクレー作品を購入して設立したもので、コレクションは現在129点に増えている。展覧会では具象と抽象、絵画と音楽、線と色彩といった「あいだ」に潜む魅力を探る。2028年1月19日から4月9日まで東京都美術館に巡回する。', '', '展覧会', 'https://www.tokyoartbeat.com/articles/-/paul-klee-in-between-worlds-news-202610',
        null, null, null)
on conflict (source_url) do nothing;

insert into public.trending_articles (title, summary, content, image_url, keyword, source_url,
    image_license, image_credit, image_page)
values ('森万里子、24年ぶりの国内大規模個展が森美術館で開幕', '約40点で30年以上の活動をたどる「森万里子：燦燦」が森美術館で開幕した。《Wave UFO》は日本初公開。', '森美術館で「森万里子：燦燦」が2026年10月31日から2027年3月28日まで開かれている。約40点で30年以上の活動をたどる大規模個展で、日本での大規模個展は2002年に東京都現代美術館で開かれた「森万里子 ピュアランド」以来24年ぶりとなる。「スター誕生」「つながる世界」「太古の記憶」「自然とひとつに」の4セクションで構成する。脳波を使うインタラクティブ作品《Wave UFO》は日本初公開。1997年のヴェネチア・ビエンナーレで特別賞を受けた《ニルヴァーナ》も展示している。キュレーションは片岡真実館長とアレクサンドラ・モンロー。', '', '展覧会', 'https://bijutsutecho.com/magazine/news/report/33273',
        null, null, null)
on conflict (source_url) do nothing;

insert into public.trending_articles (title, summary, content, image_url, keyword, source_url,
    image_license, image_credit, image_page)
values ('「志賀理江子 なぬもかぬも」が青森県立美術館で開幕', '青森県立美術館の開館20周年記念展として、東北を見つめてきた志賀理江子の過去最大規模の展覧会が始まった。', '青森県立美術館で「志賀理江子 なぬもかぬも」が2026年10月31日から2027年3月14日まで開かれている。同館の開館20周年を記念する展覧会で、東日本大震災から15年を振り返る場としても位置づけられている。2008年から宮城県に移り住んだ志賀にとって、過去最大規模の展覧会となる。宮城、福島、山形、秋田、岩手、青森の風土や歴史、風景を軸に、写真、映像、テキスト、インスタレーションなどの新作と旧作を展示する。展示の中心は、三陸沿岸部の風習から着想した架空の人物「褜男（えなお）」の物語である。', '', '展覧会', 'https://bijutsutecho.com/magazine/news/report/33271',
        null, null, null)
on conflict (source_url) do nothing;

insert into public.trending_articles (title, summary, content, image_url, keyword, source_url,
    image_license, image_credit, image_page)
values ('架空の画家と前衛美術、ユアサエボシ展が練馬で開幕', '「擬態派」を名乗る現代美術家ユアサエボシの展覧会が練馬区立美術館で開幕した。架空の画家の作品として絵画を紹介している。', '練馬区立美術館で「ユアサエボシと戦後アヴァンギャルドの変身寓話集」が2026年10月31日から12月27日まで開かれている。1983年生まれのユアサエボシは、新聞や雑誌などから集めた古いイメージをコラージュして原案をつくり、それをもとに絵画を制作している。2017年ごろからは「擬態派」を名乗る。作品は、大正生まれの架空の三流画家「ユアサヱボシ」（1924〜1987）が描いたものとして発表されている。第1章では作品を制作年順に並べ、架空の画家の作品として解説するキャプションを添えている。《理想社会》や《傀儡の王》などを展示する。', '', '展覧会', 'https://bijutsutecho.com/magazine/news/report/33274',
        null, null, null)
on conflict (source_url) do nothing;

insert into public.artworks (title, title_en, artist, artist_en, year, movement_slug, collection, image_url, content,
    image_license, image_credit, image_page)
values ('眼のある風景', 'Landscape with an Eye', '靉光', 'Ai-Mitsu',
        1938,
        (select slug from public.art_movements where slug = 'surrealism'),
        '東京国立近代美術館', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/f/fc/Aimitsu-1936-Landscape_wtih_an_Eye.png/960px-Aimitsu-1936-Landscape_wtih_an_Eye.png', '1938年の第8回独立美術展に出品され、独立美術協会賞を受けた靉光の代表作です。褐色の塊のような形が画面を埋め、その奥から一つの眼がこちらを見つめています。何が描かれているのかははっきりせず、生き物とも岩とも見える形の中で、眼だけが鋭く光ります。ヨーロッパのシュルレアリスムに触れながらも、宋元画の影響も受けた靉光は、細かく塗り重ねる独自の描き方でこの不思議な世界をつくりました。翌年には福沢一郎らと美術文化協会を設立しています。',
        'Public domain', null, 'https://commons.wikimedia.org/wiki/File:Aimitsu-1936-Landscape_wtih_an_Eye.png')
on conflict (title, artist) do update set
    title_en = excluded.title_en,
    artist_en = excluded.artist_en,
    year = excluded.year,
    movement_slug = coalesce(excluded.movement_slug, public.artworks.movement_slug),
    collection = excluded.collection,
    image_url = excluded.image_url,
    content = excluded.content,
    image_license = excluded.image_license,
    image_credit = excluded.image_credit,
    image_page = excluded.image_page;

insert into public.artworks (title, title_en, artist, artist_en, year, movement_slug, collection, image_url, content,
    image_license, image_credit, image_page)
values ('三代目市川鰕蔵の竹村定之進', 'Ichikawa Ebizō as Takemura Sadanoshin', '東洲斎写楽', 'Tōshūsai Sharaku',
        1794,
        (select slug from public.art_movements where slug = 'ukiyo-e'),
        '東京国立博物館', 'https://upload.wikimedia.org/wikipedia/commons/5/52/Brooklyn_Museum_-_Ichikawa_Ebizo_as_Takemura_Sadanoshin_-_Toshusai_Sharaku.jpg', '1794年（寛政6年）5月、江戸の河原崎座で上演された「恋女房染分手綱」で、能役者の竹村定之進を演じた市川鰕蔵を描いた役者絵です。役者の顔を大きくとらえる「大首絵」で、背景には雲母を刷り込んだ黒い地が使われています。大きな鼻と口、組んだ手に、名優の貫禄が誇張されて表れています。写楽はこの年から約10か月の間に、およそ140点の作品を残して姿を消しました。役者を美しく見せるより、その個性をとらえた描き方が、浮世絵の役者絵に新しい表現をもたらしました。',
        'Public domain', null, 'https://commons.wikimedia.org/wiki/File:Brooklyn_Museum_-_Ichikawa_Ebizo_as_Takemura_Sadanoshin_-_Toshusai_Sharaku.jpg')
on conflict (title, artist) do update set
    title_en = excluded.title_en,
    artist_en = excluded.artist_en,
    year = excluded.year,
    movement_slug = coalesce(excluded.movement_slug, public.artworks.movement_slug),
    collection = excluded.collection,
    image_url = excluded.image_url,
    content = excluded.content,
    image_license = excluded.image_license,
    image_credit = excluded.image_credit,
    image_page = excluded.image_page;

insert into public.artworks (title, title_en, artist, artist_en, year, movement_slug, collection, image_url, content,
    image_license, image_credit, image_page)
values ('吹雪-港の沖合の蒸気船', 'Snow Storm: Steam-Boat off a Harbour''s Mouth', 'J・M・W・ターナー', 'J. M. W. Turner',
        1842,
        (select slug from public.art_movements where slug = 'romanticism'),
        'テート', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/3/30/Joseph_Mallord_William_Turner_-_Snow_Storm_-_Steam-Boat_off_a_Harbour%27s_Mouth_-_WGA23178.jpg/960px-Joseph_Mallord_William_Turner_-_Snow_Storm_-_Steam-Boat_off_a_Harbour%27s_Mouth_-_WGA23178.jpg', '1842年にターナーが発表した作品です。中央の蒸気船はぼんやりとした塊にすぎず、渦を巻く波や水しぶき、吹雪が画面全体を覆っています。ターナーはこの絵のために船のマストに4時間縛りつけられて嵐を観察したという逸話が残っています。発表当時は「石鹸水と水漆喰で描かれた」と酷評されました。ロマン主義が求めた自然の巨大な力の表現を受け継ぎながら、形よりも大気と光の動きを描こうとした晩年の作風がよく表れ、のちの印象派を先取りした作品ともいわれます。',
        'Public domain', null, 'https://commons.wikimedia.org/wiki/File:Joseph_Mallord_William_Turner_-_Snow_Storm_-_Steam-Boat_off_a_Harbour''s_Mouth_-_WGA23178.jpg')
on conflict (title, artist) do update set
    title_en = excluded.title_en,
    artist_en = excluded.artist_en,
    year = excluded.year,
    movement_slug = coalesce(excluded.movement_slug, public.artworks.movement_slug),
    collection = excluded.collection,
    image_url = excluded.image_url,
    content = excluded.content,
    image_license = excluded.image_license,
    image_credit = excluded.image_credit,
    image_page = excluded.image_page;

insert into public.artworks (title, title_en, artist, artist_en, year, movement_slug, collection, image_url, content,
    image_license, image_credit, image_page)
values ('オウムと女', 'Woman with a Parrot', 'ギュスターヴ・クールベ', 'Gustave Courbet',
        1866,
        (select slug from public.art_movements where slug = 'realism'),
        'メトロポリタン美術館', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/e/e2/Woman_with_a_Parrot_MET_DT43.jpg/960px-Woman_with_a_Parrot_MET_DT43.jpg', '1866年のサロンに出品されたクールベの裸婦像です。横たわる女性が、片手に止まらせたオウムを見上げています。髪は大きく広がり、脱ぎ捨てた服が床に置かれています。神話の女神として理想化された当時の裸婦像とは違い、現実の女性の体として描かれている点に、写実主義を率いたクールベの姿勢が表れています。一方で、サロンの観客を意識したなめらかな描き方も見られます。現在はニューヨークのメトロポリタン美術館が所蔵しています。',
        'CC0', null, 'https://commons.wikimedia.org/wiki/File:Woman_with_a_Parrot_MET_DT43.jpg')
on conflict (title, artist) do update set
    title_en = excluded.title_en,
    artist_en = excluded.artist_en,
    year = excluded.year,
    movement_slug = coalesce(excluded.movement_slug, public.artworks.movement_slug),
    collection = excluded.collection,
    image_url = excluded.image_url,
    content = excluded.content,
    image_license = excluded.image_license,
    image_credit = excluded.image_credit,
    image_page = excluded.image_page;

insert into public.artists (name, name_en, short_name, born, died, region, movement_slugs, summary, body, source_url)
values ('靉光', 'Ai-Mitsu', '靉光',
        1907, 1946, 'japan', array['surrealism']::text[],
        'シュルレアリスム風の不思議な画面と宋元画の影響をあわせもつ、昭和前期の洋画家。', '本名は石村日郎で、1907年に広島県山県郡壬生町（現在の北広島町）に生まれました。印刷所で製版の技術を学んだのち、大阪の天彩画塾で絵を学び、17歳で上京して太平洋画会研究所に通いました。

1926年に二科展に初入選し、「池袋モンパルナス」と呼ばれた界隈で独自の画風を追い求めました。1930年ごろから前衛的な作品が増え、1938年に第8回独立美術展に出した《眼のある風景》で独立美術協会賞を受けました。シュルレアリスムに傾く一方で、宋元画の影響も見られます。1939年には福沢一郎らと美術文化協会を設立し、1943年には新人画会の結成に加わって3点の自画像を描きました。

1944年に召集されて中国に渡り、1946年に上海郊外で病死しました。故郷に残した作品の多くは原爆で失われ、残る作品はわずかです。生前は「異端の画家」とも呼ばれましたが、没後に高く評価されるようになりました。', 'https://ja.wikipedia.org/wiki/%E9%9D%89%E5%85%89')
on conflict (name) do update set
    name_en = excluded.name_en,
    short_name = excluded.short_name,
    born = excluded.born,
    died = excluded.died,
    region = excluded.region,
    movement_slugs = excluded.movement_slugs,
    summary = excluded.summary,
    body = excluded.body,
    source_url = excluded.source_url,
    updated_at = now();

insert into public.artists (name, name_en, short_name, born, died, region, movement_slugs, summary, body, source_url)
values ('J・M・W・ターナー', 'J. M. W. Turner', 'ターナー',
        1775, 1851, 'west', array['romanticism']::text[],
        '大気と光の表現を追い求めた、イギリス・ロマン主義を代表する風景画家。', '1775年にロンドンのコヴェント・ガーデンで理髪師の子として生まれました。学校教育はほとんど受けず、風景画家トーマス・モルトンに弟子入りしたのち、ロイヤル・アカデミー附属美術学校に入学しました。24歳で準会員、26歳で正会員となっています。

初期には写実的な風景を描き、《アルプスを越えるハンニバルとその軍勢》などで大気や光、雲を劇的に表しました。1819年のイタリア旅行で明るい陽光と色彩に魅せられ、特にヴェネツィアを何度も訪れています。その後の作品は大気と光の効果を追い、事物の形があいまいになるほどでした。

1842年の《吹雪-港の沖合の蒸気船》では、自然の巨大な力そのものを描き出し、発表当時は酷評されました。光で満たされた晩年の画面は、のちの印象派を先取りしたものともいわれます。1851年にロンドンで亡くなりました。', 'https://ja.wikipedia.org/wiki/%E3%82%B8%E3%83%A7%E3%82%BC%E3%83%95%E3%83%BB%E3%83%9E%E3%83%AD%E3%83%BC%E3%83%89%E3%83%BB%E3%82%A6%E3%82%A3%E3%83%AA%E3%82%A2%E3%83%A0%E3%83%BB%E3%82%BF%E3%83%BC%E3%83%8A%E3%83%BC')
on conflict (name) do update set
    name_en = excluded.name_en,
    short_name = excluded.short_name,
    born = excluded.born,
    died = excluded.died,
    region = excluded.region,
    movement_slugs = excluded.movement_slugs,
    summary = excluded.summary,
    body = excluded.body,
    source_url = excluded.source_url,
    updated_at = now();
